local PVPArenaTrailEnterNode = Class('PVPArenaTrailEnterNode')

------------ import ------------
local KTool           = CS.Engine.Lib.KTool
--local TimeSpan        = CS.System.TimeSpan
--local UIModule        = CS.Engine.UI.UIModule
local UIEventProxy    = CS.Engine.UI.UIEventProxy
---@type PVPArenaComponent
local pvpArenaComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)

------------ import ------------

------------ define ------------

local GetTimeHMS = CfUtils.GetTimeHMS3

------------ define ------------

function PVPArenaTrailEnterNode:__init()
end

function PVPArenaTrailEnterNode:__delete()
    self.disableRemoveCountdown = nil
end

function PVPArenaTrailEnterNode:Awake()
    UIEventProxy.Create(self.OpenBtnBg.gameObject).onPointerClick = Bind(self, self.OnClickBtnAction)
    UIEventProxy.Create(self.UnOpenBtnBg.gameObject).onPointerClick = Bind(self, self.OnClickBtnAction)
    self.__EventCountDownUpdate = Events.AddListener(Constants.EventNames.PVPArenaCountDownUpdate, Bind(self, self.OnEventCountDownUpdate))
    self.__EventRequestEntrySuccess = Events.AddListener(Constants.EventNames.PVPArenaRequestEntrySuccess, Bind(self, self.OnEventRequestEntrySuccess))
end

function PVPArenaTrailEnterNode:Start()
    --- 公示期总时间
    self.NoticeSecond      = pvpArenaComponent:GetNoticeSecond()

    pvpArenaComponent:RequestEntry()
end

function PVPArenaTrailEnterNode:OnDestroy()
    if self.__EventCountDownUpdate then
        Events.RemoveListener(Constants.EventNames.PVPArenaCountDownUpdate, self.__EventCountDownUpdate)
        self.__EventCountDownUpdate = nil
    end
    if self.__EventRequestEntrySuccess then
        Events.RemoveListener(Constants.EventNames.PVPArenaRequestEntrySuccess, self.__EventRequestEntrySuccess)
        self.__EventRequestEntrySuccess = nil
    end
    if not self.disableRemoveCountdown then
        pvpArenaComponent:RemoveCountdown()
    end

    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end

function PVPArenaTrailEnterNode:InitEntry()
    pvpArenaComponent:RequestEntry()
end

