function PVPArenaTrailEnterNode:RefreshUI()
    ---@type PVPArenaEntryDojo
    local pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    local seasonStatus      = checkNumber(pvpArenaEntryDojo.seasonStatus)
    local isOpen = seasonStatus ~= Constants.PVPArenaSeasonStatus.Closed
    KTool.SetActive(self.UnOpen.gameObject, not isOpen)
    KTool.SetActive(self.Open.gameObject, isOpen)
    if isOpen then
        self:RefreshOpenUI(pvpArenaEntryDojo)
    else
        self:RefreshUnOpenUI(pvpArenaEntryDojo)
    end

    self:OnEventCountDownUpdate()
end

---RefreshOpenUI
---@param pvpArenaEntryDojo PVPArenaEntryDojo
function PVPArenaTrailEnterNode:RefreshOpenUI(pvpArenaEntryDojo)
    local seasonId = checkNumber(pvpArenaEntryDojo.seasonId)
    self.TxtNum.text = seasonId

end

---RefreshSeasonTime
---@param pvpArenaEntryDojo PVPArenaEntryDojo
function PVPArenaTrailEnterNode:RefreshSeasonTime(pvpArenaEntryDojo)
    local seasonStatus = checkNumber(pvpArenaEntryDojo.seasonStatus)
    --- 是否是观众
    local isAudience = checkNumber(pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience
    local nextStageLeftSeconds = pvpArenaEntryDojo.nextStageLeftSeconds

    local second, text
    if seasonStatus == Constants.PVPArenaSeasonStatus.Battle then
        second = nextStageLeftSeconds
        text = localize("比赛期: _time_", { _time_ = GetTimeHMS(second, 28) })
    elseif seasonStatus == Constants.PVPArenaSeasonStatus.Notice then
        second = nextStageLeftSeconds
        local timeStr = GetTimeHMS(second, 28)
        local noticeText = localize("公示期: _time_", {_time_ = timeStr})
        local prepareText = localize("备战期: _time_", {_time_ = timeStr})
        text = isAudience and noticeText or prepareText
    elseif seasonStatus == Constants.PVPArenaSeasonStatus.Quiz then
        if isAudience then
            second = nextStageLeftSeconds
            local timeStr = GetTimeHMS(second, 28)
            text = localize("推选期: _time_", {_time_ = timeStr})
        else
            --- 参数玩家没有公式期 所以 投票阶段需要加上 公示期总时间
            second = nextStageLeftSeconds + self.NoticeSecond
            local timeStr = GetTimeHMS(second, 28)
            text = localize("备战期: _time_", {_time_ = timeStr})
        end
    end

    self.TxtNextStart.text = text

end

---RefreshUnOpenUI
---刷新未开启状态UI
---@param pvpArenaEntryDojo PVPArenaEntryDojo
function PVPArenaTrailEnterNode:RefreshUnOpenUI(pvpArenaEntryDojo)
    local second = checkNumber(pvpArenaEntryDojo.nextStageLeftSeconds)
    self:RefreshUnOpenTxtNextStart(second)
end

---RefreshUnOpenTxtNextStart
---刷新未开启状态 时间
---@param second number 时间
function PVPArenaTrailEnterNode:RefreshUnOpenTxtNextStart(second)
    self.UnOpenTxtNextStart.text = localize("距离下次竞赛：_time_", {_time_ = GetTimeHMS(second)})
end

function PVPArenaTrailEnterNode:OnEventCountDownUpdate()
    ---@type PVPArenaEntryDojo
    local pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    local seasonStatus      = checkNumber(pvpArenaEntryDojo.seasonStatus)
    if seasonStatus == Constants.PVPArenaSeasonStatus.Closed  then
        self:RefreshUnOpenTxtNextStart(checkNumber(pvpArenaEntryDojo.nextStageLeftSeconds))
    else
        self:RefreshSeasonTime(pvpArenaEntryDojo)
    end
end

function PVPArenaTrailEnterNode:OnEventRequestEntrySuccess()
    self:RefreshUI()
end

